-- Lot T9 des Tarides (03/11/2026) : marchands et services. Généré par outils\marchands_tarides.py : ne pas
-- modifier à la main. Ne touche pas aux marchands de Durotar (sauf les recettes de Blizzard, retirées).
USE acore_world;

-- Retraits de Blizzard, gardés pour le retour.
CREATE TABLE IF NOT EXISTS solazeroth_v3_t9_ventes_origine SELECT * FROM npc_vendor WHERE 1 = 0;
-- Herbes et poisons de Hula'mahi.
INSERT INTO solazeroth_v3_t9_ventes_origine SELECT v.* FROM npc_vendor v JOIN item_template i ON i.entry = v.item WHERE v.entry = 3490 AND ((i.class = 0 AND i.subclass = 8) OR (i.class = 7 AND i.subclass = 9));
-- Recettes des marchands qui n'apparaissent qu'en zones 14 et 17.
INSERT IGNORE INTO solazeroth_v3_t9_ventes_origine SELECT v.* FROM npc_vendor v JOIN item_template i ON i.entry = v.item WHERE i.class = 9 AND v.entry IN (SELECT id FROM creature GROUP BY id HAVING SUM(zoneId IN (14, 17)) > 0 AND SUM(zoneId NOT IN (14, 17)) = 0);
-- Équipement des marchands d'Orgrimmar.
INSERT IGNORE INTO solazeroth_v3_t9_ventes_origine SELECT v.* FROM npc_vendor v JOIN item_template i ON i.entry = v.item WHERE v.entry IN (SELECT DISTINCT id FROM creature WHERE zoneId = 1637) AND i.class IN (2, 4) AND i.entry < 900000 AND i.InventoryType NOT IN (0, 4, 18, 19) AND NOT (i.class = 2 AND i.subclass IN (14, 20));
DELETE v FROM npc_vendor v JOIN solazeroth_v3_t9_ventes_origine o ON o.entry = v.entry AND o.item = v.item AND o.ExtendedCost = v.ExtendedCost;

