-- Hraq, fournisseur de matériaux (v3_fournisseur.cpp) : son état d'origine pour le retour.
CREATE TABLE IF NOT EXISTS solazeroth_v3_t9_pnj_origine SELECT entry, npcflag, gossip_menu_id, ScriptName FROM creature_template WHERE entry = 3477;
UPDATE creature_template SET npcflag = 1, gossip_menu_id = 0, ScriptName = 'npc_solazeroth_v3_fournisseur' WHERE entry = 3477;
SET @manque = (SELECT COUNT(*) = 0 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = 'acore_world' AND TABLE_NAME = 'solazeroth_v3_fournisseur' AND COLUMN_NAME = 'pnj');
SET @requete = IF(@manque, 'ALTER TABLE solazeroth_v3_fournisseur ADD COLUMN pnj INT UNSIGNED NOT NULL DEFAULT 910030 FIRST, DROP PRIMARY KEY, ADD PRIMARY KEY (pnj, objet)', 'DO 0');
PREPARE sol_requete FROM @requete;
EXECUTE sol_requete;
DEALLOCATE PREPARE sol_requete;
DELETE FROM solazeroth_v3_fournisseur WHERE pnj = 3477;
